inlineScript.scriptBlock:
this.callInitObject = function(val){
console.log(val);
	if(val == this.context.options.newRequest.get("value") && this.context.options.dataRetrieved.get("value")){
		console.log("DONE");
		this.ui.get("CIFNO").setData("");
		this.ui.get("customerName").setData("");
		this.ui.get("retrieveCustomerBtn").setVisible(false,true);
		this.ui.get("initialize").click();
	}
}



///show parent request number if request nature is update request
this.showParentRequestNo = function(){
	if(this.context.binding.get("value").get("requestNature").get("value") == "update" && this.context.binding.get("value").get("requestType").get("name") != "" && this.context.options.retrieveCustomer.get("value") == true){
		//this.context.options.parentrequestTypeVIS.set("Editable",  "NONE");
		this.ui.get("updateRequestTypeSection").setVisible(true,true);
	}
	else{
		//this.context.options.parentrequestTypeVIS.set("value",  "NONE");
		this.ui.get("updateRequestTypeSection").setVisible(false,true);
	}
	
	
}
// hide create contract if request nature , request type , cif no and parent request no is empty
this.showCreateBtn = function(){
	if(this.context.binding.get("value").get("requestNature").get("value") == "" ||this.context.binding.get("value").get("requestType").get("value") == "" ||this.context.binding.get("value").get("cif") == "" || this.context.binding.get("value").get("customerName")=="" ||
	(this.context.binding.get("value").get("requestNature").get("value") == "update" && (this.context.binding.get("value").get("parentRequestNo") == "" || this.context.binding.get("value").get("ImporterName") == "" ) ))
	{
	 	this.ui.get("createRequestBtn").setVisible(false,true);
	}
	else{
		this.ui.get("createRequestBtn").setVisible(true,true);	
	}
}

